<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>گزارش پورسانت {{ $document->document_number }}</title><style>body{font-family:Tahoma;direction:rtl;margin:30px}h1{text-align:center}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border:1px solid #777;padding:7px;text-align:right}.meta{display:flex;justify-content:space-between}.total{font-weight:bold}@media print{button{display:none}}</style></head><body><button onclick="print()">چاپ</button><h1>شرکت آریا گستر — گزارش پورسانت مالی</h1><div class="meta"><span>شماره: {{ $document->document_number }}</span><span>فروشنده: {{ $document->seller?->name }}</span><span>دوره: {{ App\Support\JalaliDate::date($document->period_from) }} تا {{ App\Support\JalaliDate::date($document->period_to) }}</span></div><table><thead><tr><th>فاکتور</th><th>مشتری</th><th>فروش</th><th>نرخ</th><th>پورسانت</th></tr></thead><tbody>@foreach($document->items as $item)<tr><td>{{ $item->invoice_number_snapshot }}</td><td>{{ $item->customer_name_snapshot }}</td><td>{{ number_format($item->item_net_amount) }}</td><td>{{ $item->rate_snapshot }}٪</td><td>{{ number_format($item->commission_amount) }}</td></tr>@endforeach</tbody><tfoot><tr class="total"><td colspan="2">جمع</td><td>{{ number_format($document->total_sales_amount) }} ریال</td><td></td><td>{{ number_format($document->total_commission_amount) }} ریال</td></tr></tfoot></table></body></html>
